import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  createdAt: Date
}

const posts: Post[] = []

export async function addPost(title: string): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    createdAt: new Date(),
  }
  posts.push(post)
  return post
}

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return [...posts]
}

